<?php
namespace App\Commands\AiOps\N8n; use App\Commands\SafeBaseCommand; use App\Commands\Support\SubsCommandTrait; use CodeIgniter\CLI\CLI;
class Logs extends SafeBaseCommand { use SubsCommandTrait; protected $group = 'AIOps'; protected $name='aiops:n8n:logs'; protected $description='Tail n8n logs'; protected $options=['--lines'=>'Lines','--json'=>'JSON']; public function run(array $params){$this->parseParams($params);$lines=$this->optInt('lines', 200);$r=$this->mgr()->tailLogs('aiops.n8n',$lines); if(!$this->optBool('json')){foreach($r['lines']??[] as $line){CLI::write($line);} } else {$this->emit($r,true);} return ($r['ok']??false)?EXIT_SUCCESS:EXIT_ERROR;}}
